def list_tasks(
    tasks: list[dict],
    *,
    status: str | None = None,
    limit: int = 20,
    offset: int = 0,
) -> list[dict]:
    """返回任务列表的查询结果，不修改输入列表。"""
    if limit < 1 or offset < 0:
        raise ValueError("limit must be at least 1 and offset must be non-negative")

    if status is not None:
        filtered = [task for task in tasks if task["status"] == status]
    else:
        filtered = list(tasks)

    page = filtered[offset:offset + limit]
    return page
